canvas.addEventListener('pointerdown',e=>{if(paused)return;if(!started){start();return;}const x=e.clientX,y=e.clientY;const hit=[...sheep].sort((a,b)=>a.z-b.z).find(a=>{const p=a.screen;return p&&Math.abs(x-p.x)<p.w*.5&&y<p.y+8&&y>p.y-p.h;});if(hit){selected=hit;hit.pet=2;notify(hit.name+'의 폭신한 털을 살살 쓰다듬었어요.');baa(.1);return;}selected=null;if(seated){notify('일어나기 버튼을 누르면 다시 걸을 수 있어요.');return;}if(y<H*.51)return;const depth=H*.64*14/(y-H*.36),z=clamp(depth-14+cam.z,0,30),scale=Math.min(W*.95,950)/depth;player.tx=clamp((x-W*.5)/scale+cam.x,-18,18);player.tz=z;marker={x:player.tx,z};});
